   451  otError Ip6::SendDatagram(Message &aMessage, MessageInfo &aMessageInfo, IpProto aIpProto)
   452  {
   453      otError                    error = OT_ERROR_NONE;
   454      Header                     header;
   455      uint16_t                   payloadLength = aMessage.GetLength();
   456      uint16_t                   checksum;
   457      const NetifUnicastAddress *source;
   458
   459      header.Init();
   460      header.SetDscp(PriorityToDscp(aMessage.GetPriority()));
   461      header.SetPayloadLength(payloadLength);
   462      header.SetNextHeader(aIpProto);
   463      header.SetHopLimit(aMessageInfo.mHopLimit ? aMessageInfo.mHopLimit : static_cast<uint8_t>(kDefaultHopLimit));
   464
   465      if (aMessageInfo.GetSockAddr().IsUnspecified() || aMessageInfo.GetSockAddr().IsMulticast())
   466      {
   467          VerifyOrExit((source = SelectSourceAddress(aMessageInfo)) != NULL, error = OT_ERROR_INVALID_SOURCE_ADDRESS);
   468          header.SetSource(source->GetAddress());
   469      }
   470      else
   471      {
   472          header.SetSource(aMessageInfo.GetSockAddr());
   473      }
   474
   475      header.SetDestination(aMessageInfo.GetPeerAddr());
   476
   477      if (aMessageInfo.GetPeerAddr().IsRealmLocalMulticast())
   478      {
   479          SuccessOrExit(error = AddMplOption(aMessage, header));
   480      }
   481
   482      SuccessOrExit(error = aMessage.Prepend(&header, sizeof(header)));
   483
   484      // compute checksum
   485      checksum = ComputePseudoheaderChecksum(header.GetSource(), header.GetDestination(), payloadLength, aIpProto);
   486
   487      switch (aIpProto)
   488      {
   489      case kProtoUdp:
   490          mUdp.UpdateChecksum(aMessage, checksum);
   491          break;
   492
   493      case kProtoIcmp6:
   494          mIcmp.UpdateChecksum(aMessage, checksum);
   495          break;
   496
   497      default:
   498          break;
   499      }
   500
   501      if (aMessageInfo.GetPeerAddr().IsMulticastLargerThanRealmLocal())
   502      {
   503          if (Get<Mle::MleRouter>().HasSleepyChildrenSubscribed(header.GetDestination()))
   504          {
   505              Message *messageCopy = NULL;
   506
   507              if ((messageCopy = aMessage.Clone()) != NULL)
   508              {
   509                  otLogInfoIp6("Message copy for indirect transmission to sleepy children");
   510                  EnqueueDatagram(*messageCopy);
   511              }
   512              else
   513              {
   514                  otLogWarnIp6("No enough buffer for message copy for indirect transmission to sleepy children");
   515              }
   516          }
   517
   518          SuccessOrExit(error = AddTunneledMplOption(aMessage, header, aMessageInfo));
   519      }
   520
   521  exit:
   522
   523      if (error == OT_ERROR_NONE)
   524      {
   525          if (aMessage.GetLength() > kMaxDatagramLength)
   526          {
   527              error = FragmentDatagram(aMessage, aIpProto);
   528          }
   529          else
   530          {
   531              EnqueueDatagram(aMessage);
   532          }
   533      }
   534
   535      return error;
   536  }
